// TestRunScriptRender pins runScript's byte format, with and without its
// optional parts; the per-family tests pin what goes into it.
func TestRunScriptRender(t *testing.T) {
	plain := runScript{Binary: "/opt/node", Args: []string{"node", "--flag", "it's"}}
	want := `#!/bin/sh
# auto-generated by evm-benchmark

cd "$(dirname "$0")"

exec '/opt/node' \
  'node' \
  '--flag' \
  'it'\''s'
`
	if got := plain.render(); got != want {
		t.Errorf("plain run.sh mismatch:\n--- got ---\n%s\n--- want ---\n%s", got, want)
	}

	full := runScript{Binary: "node", Args: []string{"run"}, Note: " (docker)", Strict: true, Preamble: []string{"A=1", "export A"}}
	want = `#!/bin/sh
# auto-generated by evm-benchmark (docker)

set -eu

cd "$(dirname "$0")"

A=1
export A

exec 'node' \
  'run'
`
	if got := full.render(); got != want {
		t.Errorf("full run.sh mismatch:\n--- got ---\n%s\n--- want ---\n%s", got, want)
	}
}

// TestPortBlockDefaultBase covers the one branch the per-family port tests do
// not: both pass an explicit base, so nothing else pins what happens when the
// spec leaves it unset.
func TestPortBlockDefaultBase(t *testing.T) {
	block := portBlock{defaultBase: 9000, size: 4, rpcOffset: 3}
	if got := block.rpc(0, 2); got != 9011 {
		t.Errorf("rpc(unset, 2) = %d, want 9011 (default base + 2 blocks + offset)", got)
	}
}

// TestDevnetLaunchCommand pins that the launcher is looked up where the
// generators write it; the gated bootstrap tests are the only other check, and
// they skip without the chain binaries.
func TestDevnetLaunchCommand(t *testing.T) {
	spec := messages.BenchmarkSpec{DataDir: "/tmp/bench"}
	argv, dir := devnetLaunchCommand(spec, messages.NodeTarget{GlobalSeq: 2})
	if len(argv) != 1 || argv[0] != "/tmp/bench/devnet/node2/run.sh" || dir != "/tmp/bench/devnet/node2" {
		t.Errorf("devnetLaunchCommand = %v, %q", argv, dir)
	}
}

// TestDevnetBootstrapRefusesOccupiedPort pins each family's stale-node guard
// (assertRPCPortsFree).
func TestDevnetBootstrapRefusesOccupiedPort(t *testing.T) {
	port := busyPort(t)
	for name, tc := range map[string]struct {
		chain ChainRuntime
		spec  messages.BenchmarkSpec
	}{
		"allegro": {allegroRuntime{}, messages.BenchmarkSpec{AllegroBasePort: port - allegroHTTPPortOffset}},
		"reth":    {rethRuntime{}, messages.BenchmarkSpec{RethBasePort: port - rethHTTPPortOffset}},
		"tempo":   {tempoRuntime{}, messages.BenchmarkSpec{TempoBasePort: port - tempoHTTPPortOffset}},
	} {
		tc.spec.DataDir = t.TempDir()
		err := tc.chain.Bootstrap(context.Background(), tc.spec, []messages.NodeTarget{{GlobalSeq: 0}})
		if err == nil || !strings.Contains(err.Error(), "already in use") {
			t.Errorf("%s: err = %v, want bootstrap to refuse an occupied RPC port", name, err)
		}
	}
}

// TestRethTxPoolArgsCoverTheLoad guards the failure mode the pool sizing exists
// for. reth refuses transactions past max-account-slots outright: a run with
// num_txs 250 against the default 16 (or a hardcoded 100) had 2000*(250-100) =
// 300,000 of its 500,000 rejected and reported a rate that measured nothing.
// Slots must cover num_txs, and the sub-pools the whole load.
func TestRethTxPoolArgsCoverTheLoad(t *testing.T) {
	// Sizes are 200k * 512B, in MB.
	got := rethTxPoolArgs(messages.BenchmarkSpec{NumAccounts: 2000, NumTxs: 100})
	want := strings.Fields(`--txpool.max-account-slots 100 --txpool.pending-max-count 200000 --txpool.pending-max-size 98
		--txpool.queued-max-count 200000 --txpool.queued-max-size 98`)
	if !slices.Equal(got, want) {
		t.Errorf("pool args = %v, want %v", got, want)
	}

	// A small load must not shrink the pool below reth's own defaults.
	got = rethTxPoolArgs(messages.BenchmarkSpec{NumAccounts: 1, NumTxs: 1})
	want = strings.Fields(`--txpool.max-account-slots 16 --txpool.pending-max-count 10000 --txpool.pending-max-size 20
		--txpool.queued-max-count 10000 --txpool.queued-max-size 20`)
	if !slices.Equal(got, want) {
		t.Errorf("small-load pool args = %v, want reth's defaults %v", got, want)
	}
}

func TestPatchGenesisJSONPreservesLargeInts(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "genesis.json")
	orig := `{"alloc":{"0xabc":{"balance":18446744073709551615}},"config":{"chainId":1337,"keep":true}}`
	if err := os.WriteFile(path, []byte(orig), 0o644); err != nil {
		t.Fatal(err)
	}
	patch := map[string]interface{}{
		"config": map[string]interface{}{"chainId": 9999},
	}
	if err := patchGenesisJSON(path, patch); err != nil {
		t.Fatalf("patchGenesisJSON: %v", err)
	}
	out, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	got := string(out)
	if !strings.Contains(got, "18446744073709551615") {
		t.Errorf("large balance corrupted (scientific notation?):\n%s", got)
	}
	if !strings.Contains(got, "9999") || !strings.Contains(got, `"keep": true`) {
		t.Errorf("patch merge wrong (want chainId 9999, keep true):\n%s", got)
	}
}

// TestDeepMergeJSON guards the genesis-patch semantics: nested objects merge
// recursively while scalars and arrays are replaced wholesale.
func TestDeepMergeJSON(t *testing.T) {
	dst := map[string]interface{}{
		"config": map[string]interface{}{"chainId": float64(1), "keep": "me"},
		"scalar": "old",
	}
	src := map[string]interface{}{
		"config": map[string]interface{}{"chainId": float64(2)},
		"scalar": "new",
	}
	out := deepMergeJSON(dst, src)
	cfg := out["config"].(map[string]interface{})
	if cfg["chainId"] != float64(2) {
		t.Errorf("chainId not overridden: %v", cfg["chainId"])
	}
	if cfg["keep"] != "me" {
		t.Errorf("sibling key dropped during merge: %v", cfg)
	}
	if out["scalar"] != "new" {
		t.Errorf("scalar not replaced: %v", out["scalar"])
	}
}

// assertScript compares launchers through render, so a mismatch prints both as
// they would be written.
func assertScript(t *testing.T, got, want runScript) {
	t.Helper()
	if g, w := got.render(), want.render(); g != w {
		t.Errorf("run.sh mismatch:\n--- got ---\n%s\n--- want ---\n%s", g, w)
	}
}

// flagValue returns the argument following name in args, or "" if args does
// not pass it.
func flagValue(args []string, name string) string {
	if i := slices.Index(args, name); i >= 0 && i+1 < len(args) {
		return args[i+1]
	}
	return ""
}

// signedSenders recovers the senders of a node's transactions from the shared
// signer, so a test checks the accounts a run really pays from.
func signedSenders(t *testing.T, spec messages.BenchmarkSpec, globalSeq int) []common.Address {
	t.Helper()
	raws, err := bench.GenerateSignedTxs(spec, globalSeq)
	if err != nil {
		t.Fatalf("GenerateSignedTxs: %v", err)
	}
	signer := types.NewLondonSigner(big.NewInt(spec.EVMChainID))
	senders := make([]common.Address, len(raws))
	for i, raw := range raws {
		var tx types.Transaction
		if err := tx.UnmarshalBinary(common.FromHex(raw)); err != nil {
			t.Fatalf("decode tx %d: %v", i, err)
		}
		if senders[i], err = types.Sender(signer, &tx); err != nil {
			t.Fatalf("recover sender of tx %d: %v", i, err)
		}
	}
	return senders
}
